test('concurrency refresh rejects impossible runtime counts and preserves the previous snapshot',async()=>{
 let bad=false;const {dom}=await render(async url=>url.endsWith('/settings/concurrency')?{ok:true,json:async()=>({...concurrencySnapshot(),admitted_files:bad?3:1})}:{ok:true,json:async()=>({batches:[]})});
 try{const d=dom.window.document;d.querySelector('[data-testid=upload-concurrency-toggle]').click();await tick();await tick();bad=true;d.querySelector('[data-testid=upload-concurrency-refresh]').click();await tick();await tick();const panel=d.querySelector('[data-testid=upload-concurrency-settings]');assert.match(panel.textContent,/已准入 1/);assert.match(panel.textContent,/响应无效/);assert.equal(d.querySelector('[data-testid=upload-concurrency-save]').disabled,true);}finally{dom.window.close()}
});
test('closing and reopening concurrency settings ignores an old successful save response',async()=>{
 let release;const {dom,requests}=await render(async(url,init)=>url.endsWith('/settings/concurrency')?(init.method==='POST'?new Promise(r=>release=r):{ok:true,json:async()=>concurrencySnapshot()}):{ok:true,json:async()=>({batches:[]})});
 try{const d=dom.window.document;const toggle=d.querySelector('[data-testid=upload-concurrency-toggle]');toggle.click();await tick();await tick();const select=d.querySelector('[data-testid=upload-concurrency-settings] select');select.value='2';select.dispatchEvent(new dom.window.Event('change',{bubbles:true}));await tick();d.querySelector('[data-testid=upload-concurrency-save]').click();await tick();toggle.click();await tick();toggle.click();await tick();await tick();release({ok:true,json:async()=>({...concurrencySnapshot(2),updated_at_utc:'2026-11-05T14:01:00Z'})});await tick();await tick();const panel=d.querySelector('[data-testid=upload-concurrency-settings]');assert.match(panel.textContent,/当前设置 1/);assert.match(panel.textContent,/上次保存响应未确认/);assert.equal(requests.filter(r=>r.method==='POST').length,1);}finally{dom.window.close()}
});
test('concurrency BFCache restoration ignores a late authorization failure',async()=>{
 let release;const {dom}=await render(async url=>url.endsWith('/settings/concurrency')?new Promise(r=>release=r):{ok:true,json:async()=>({batches:[]})});
 try{const d=dom.window.document;d.querySelector('[data-testid=upload-concurrency-toggle]').click();await tick();dom.window.dispatchEvent(new dom.window.PageTransitionEvent('pagehide',{persisted:true}));dom.window.dispatchEvent(new dom.window.PageTransitionEvent('pageshow',{persisted:true}));release({ok:false,status:401});await tick();await tick();assert.equal(d.querySelector('[data-testid=upload-concurrency-toggle]').disabled,false);assert.equal(d.querySelector('[data-testid=upload-concurrency-toggle]').getAttribute('aria-expanded'),'false');}finally{dom.window.close()}
});


const storageFixture=(override={})=>({directory:'D:/state/uploads',staging_bytes:'2405652891274',staging_files:'2',partial:false,disappeared_files:'0',scan_started_at_utc:'2026-11-05T16:40:00Z',scan_finished_at_utc:'2026-11-05T16:40:01Z',available_bytes:'1024',available_error:'',available_checked_at_utc:'2026-11-05T16:40:02Z',...override});
test('upload storage is lazy and shows logical staging separately from unreserved free capacity',async()=>{
 const {dom,requests}=await render(async url=>({ok:true,json:async()=>url==='/api/uploads/storage'?storageFixture():{batches:[]}}));try{assert.equal(requests.length,1);const d=dom.window.document,b=d.querySelector('[data-testid=upload-storage-open]');assert.ok(b);b.click();await tick();await tick();const panel=d.querySelector('[data-testid=upload-storage-panel]');assert.match(panel.textContent,/2.19 TiB/);assert.match(panel.textContent,/1 KiB/);assert.match(panel.textContent,/未预留|不.*预留/);assert.match(panel.textContent,/逻辑/);assert.ok(requests.every(r=>r.method==='GET'));}finally{dom.window.close();}
});
test('failed upload storage refresh preserves the old observation without claiming current capacity',async()=>{
 let failed=false;const {dom}=await render(async url=>url==='/api/uploads/storage'?(failed?{ok:false,status:503}:{ok:true,json:async()=>storageFixture()}):{ok:true,json:async()=>({batches:[]})});try{const d=dom.window.document;d.querySelector('[data-testid=upload-storage-open]').click();await tick();await tick();failed=true;d.querySelector('[data-testid=upload-storage-refresh]').click();await tick();await tick();const p=d.querySelector('[data-testid=upload-storage-panel]');assert.match(p.textContent,/上次.*快照/);assert.match(p.textContent,/2.19 TiB/);assert.equal(p.querySelector('[data-testid=upload-storage-shortage]'),null);}finally{dom.window.close();}
});
test('unavailable capacity is unknown rather than zero and late storage authorization cannot affect a new view',async()=>{
 let finish,delay=true;const {dom}=await render(async url=>url==='/api/uploads/storage'?(delay?new Promise(r=>finish=r):{ok:true,json:async()=>storageFixture({available_bytes:null,available_error:'磁盘探测不可用'})}):{ok:true,json:async()=>({batches:[]})});try{const d=dom.window.document;d.querySelector('[data-testid=upload-storage-open]').click();await tick();d.querySelector('[data-testid=upload-storage-open]').click();await tick();delay=false;d.querySelector('[data-testid=upload-storage-open]').click();await tick();await tick();finish({ok:false,status:401});await tick();await tick();const p=d.querySelector('[data-testid=upload-storage-panel]');assert.match(p.textContent,/未知/);assert.match(p.textContent,/磁盘探测不可用/);assert.doesNotMatch(d.body.textContent,/管理员登录已失效/);}finally{finish?.({ok:false,status:401});dom.window.close();}
});

test('storage shortage follows the current selected files and never starts an upload itself',async()=>{
 const {dom,requests}=await render(async url=>({ok:true,json:async()=>url==='/api/uploads/storage'?storageFixture({available_bytes:'1'}):{batches:[]}}));try{const d=dom.window.document;selectFile(dom);await tick();d.querySelector('[data-testid=upload-storage-open]').click();await tick();await tick();assert.ok(d.querySelector('[data-testid=upload-storage-shortage]'));assert.match(d.querySelector('[data-testid=upload-storage-panel]').textContent,/3 B/);assert.ok(requests.every(r=>r.method==='GET'));assert.equal(d.querySelector('[data-testid=upload-start]').disabled,true);}finally{dom.window.close();}
});

test('upload history successful empty page explains its state and local read time',async()=>{const {dom}=await render(async()=>({ok:true,json:async()=>({batches:[]})}));try{const panel=dom.window.document.querySelector('[data-testid=upload-history]');assert.ok(panel);assert.match(panel.textContent,/暂无上传批次/);assert.match(panel.textContent,/本机读取 UTC/);}finally{dom.window.close();}});
test('upload history first loading and failure never claim a successful empty list',async()=>{let finish;const {dom}=await render(async url=>url==='/api/uploads'?new Promise(resolve=>finish=()=>resolve({ok:false,status:503,text:async()=>'历史不可读'})):{ok:true,json:async()=>({})});try{const panel=dom.window.document.querySelector('[data-testid=upload-history]');assert.ok(panel);assert.match(panel.textContent,/正在读取上传批次/);assert.doesNotMatch(panel.textContent,/暂无上传批次/);finish();await tick();await tick();assert.match(panel.textContent,/上传历史暂不可读/);assert.doesNotMatch(panel.textContent,/暂无上传批次/);}finally{finish?.();dom.window.close();}});

test('upload history failure retains prior rows and observation instead of claiming empty',async()=>{let fail=false;const {dom}=await render(async()=>fail?{ok:false,status:503,text:async()=>'history offline'}:{ok:true,json:async()=>({batches:[{id:'a'.repeat(32),target:'/saved-target',completed:1,total:1,failed:0,unknown:0,created_at_utc:'2026-11-04T00:00:00Z'}]})});try{const panel=dom.window.document.querySelector('[data-testid=upload-history]');const observed=panel.textContent.match(/本机读取 UTC：([^；]+)/)[1];fail=true;dom.window.dispatchEvent(new dom.window.Event('pagehide'));const event=new dom.window.Event('pageshow');Object.defineProperty(event,'persisted',{value:true});dom.window.dispatchEvent(event);await tick();await tick();assert.match(panel.textContent,/saved-target/);assert.match(panel.textContent,/仅供历史查看/);assert.ok(panel.textContent.includes(observed));assert.equal(panel.querySelector('[data-testid=upload-history-empty]'),null);}finally{dom.window.close();}});
test('upload history polling keeps an observed empty snapshot while the next read is pending',async()=>{let poll,finish,reads=0;const {dom}=await render(async url=>url==='/api/uploads'?(++reads===1?{ok:true,json:async()=>({batches:[]})}:new Promise(resolve=>finish=()=>resolve({ok:true,json:async()=>({batches:[]})}))):{ok:true,json:async()=>({})},'',dom=>{const original=dom.window.setTimeout.bind(dom.window);dom.window.setTimeout=(fn,ms,...args)=>{if(ms===2000){poll=fn;return 900000;}return original(fn,ms,...args);};});try{const panel=dom.window.document.querySelector('[data-testid=upload-history]');assert.ok(panel.querySelector('[data-testid=upload-history-empty]'));poll();await tick();assert.ok(panel.querySelector('[data-testid=upload-history-empty]'));assert.doesNotMatch(panel.textContent,/正在读取上传批次/);finish();await tick();await tick();assert.ok(panel.querySelector('[data-testid=upload-history-empty]'));}finally{finish?.();dom.window.close();}});

test('current upload history 401 preserves observed rows but disables upload controls',async()=>{let poll,expired=false;const {dom}=await render(async()=>expired?{ok:false,status:401}:{ok:true,json:async()=>({batches:[{id:'a'.repeat(32),target:'/saved',total:1,completed:1,failed:0,unknown:0}]})},'',dom=>{const original=dom.window.setTimeout.bind(dom.window);dom.window.setTimeout=(fn,ms,...args)=>{if(ms===2000){poll=fn;return 900000;}return original(fn,ms,...args);};});try{const panel=dom.window.document.querySelector('[data-testid=upload-history]'),observed=panel.textContent.match(/本机读取 UTC：([^；]+)/)[1];expired=true;poll();await tick();await tick();assert.match(panel.textContent,/saved/);assert.match(panel.textContent,/请重新登录/);assert.ok(panel.textContent.includes(observed));assert.equal(dom.window.document.querySelector('[data-testid=upload-target]').disabled,true);}finally{dom.window.close();}});
for(const late of ['401','JSON'])test('restored upload history ignores old '+late+' without losing its fresh empty observation',async()=>{let finish,reads=0;const {dom}=await render(async()=>++reads===1?(late==='401'?new Promise(resolve=>finish=()=>resolve({ok:false,status:401})):{ok:true,json:()=>new Promise(resolve=>finish=()=>resolve({batches:[{id:'a'.repeat(32),target:'/old'}]}))}):{ok:true,json:async()=>({batches:[]})});try{dom.window.dispatchEvent(new dom.window.Event('pagehide'));const event=new dom.window.Event('pageshow');Object.defineProperty(event,'persisted',{value:true});dom.window.dispatchEvent(event);await tick();await tick();const panel=dom.window.document.querySelector('[data-testid=upload-history]'),observed=panel.textContent.match(/本机读取 UTC：([^；]+)/)[1];finish();await tick();await tick();assert.ok(panel.querySelector('[data-testid=upload-history-empty]'));assert.ok(panel.textContent.includes(observed));assert.doesNotMatch(panel.textContent,/old|请重新登录/);assert.equal(dom.window.document.querySelector('[data-testid=upload-target]').disabled,false);}finally{finish?.();dom.window.close();}});

test('upload settings stay secondary to the actual upload form',async()=>{
 const {dom,requests}=await render(async()=>({ok:true,json:async()=>({batches:[]})}));try{const d=dom.window.document,panel=d.querySelector('[data-testid=upload-concurrency-toggle]').closest('details');assert.ok(panel);assert.equal(panel.open,false);assert.match(panel.querySelector('summary').textContent,/上传设置/);assert.ok(d.querySelector('[data-testid=upload-start]'));assert.ok(requests.every(r=>r.method==='GET'));}finally{dom.window.close()}
});
